/* Glider tooltip card (same look as the Mount card). Position comes inline from Module:Glider. */
.aa-glider {
  display: flow-root;
  position: relative;
  box-sizing: border-box;
  width: 300px;
  max-width: 100%;
  padding: 10px 12px;
  background: linear-gradient(to bottom, rgba(24, 28, 38, 0.97), rgba(10, 12, 18, 0.97));
  border: 1px solid #5a5040;
  border-radius: 3px;
  box-shadow: 0 0 0 1px #000, 0 4px 12px rgba(0, 0, 0, 0.6);
  margin: 0 0 0.5em 0; /* small gap so cards stack nicely */
  color: #e8e4d8;
  font-size: 13px;
  line-height: 1.5;
  text-align: left;
}

/* Header: icon, category, name */
.aa-glider-head {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-bottom: 6px;
}
.aa-glider-icon {
  line-height: 0;
}
.aa-glider-title {
  display: flex;
  flex-direction: column;
  line-height: 1.3;
}
.aa-glider-cat {
  color: #e8e4d8;
}
.aa-glider-name {
  font-size: 16px;
  font-weight: bold;
}
.aa-glider-sep {
  height: 1px;
  margin: 6px 0;
  background: linear-gradient(to right, transparent, #6a5d48, transparent);
}

.aa-glider-grade {
  font-size: 13px;
}

/* Description and flight stats */
.aa-glider-desc {
  color: #e8e4d8;
}
.aa-glider-stats {
  margin-top: 10px;
  color: #e8e4d8;
}
/* Special Skill: one skill per row, lined up under each other */
.aa-glider-skillrow {
  display: flex;
  gap: 0.25em;
}
.aa-glider-skilllabel {
  flex: 0 0 auto;
}
.aa-glider-skills {
  display: block;
}
/* A card floated to the right opens its skill boxes towards the left, so they stay on the screen */
.aa-glider-right .aa-mskill-tip {
  left: auto;
  right: 0;
}

/* Use / Equip effect */
.aa-glider-label {
  margin-top: 10px;
  color: #8a8478;
}
.aa-glider-green {
  color: #9acd32;
}

/* Phones: a floated card gets its own line instead of squeezing the text */
@media (max-width: 500px) {
  .aa-glider-float {
    float: none !important;
    clear: both !important;
    margin: 0 0 0.5em 0 !important;
  }
  /* skill hover boxes become a panel at the bottom of the screen (tap a skill to open) */
  .aa-glider .aa-mskill-tip {
    position: fixed;
    left: 0.5em;
    right: 0.5em;
    top: auto;
    bottom: 0.5em;
    width: auto;
    max-height: 60vh;
    overflow-y: auto;
    margin-top: 0;
  }
}
